from __future__ import annotations

from decimal import Decimal, ROUND_HALF_UP
from functools import cmp_to_key
from typing import Any


_CENT = Decimal("0.01")


def _money(value: Any) -> Decimal:
    if value is None:
        return Decimal("0.00")
    if isinstance(value, str) and not value.strip():
        return Decimal("0.00")
    return Decimal(str(value)).quantize(_CENT, rounding=ROUND_HALF_UP)


def _ascending_compare(left: Any, right: Any) -> int:
    try:
        if left < right:
            return -1
        if left > right:
            return 1
        return 0
    except TypeError:
        left_key = (type(left).__name__, repr(left))
        right_key = (type(right).__name__, repr(right))
        return (left_key > right_key) - (left_key < right_key)


def sweep(
    accounts: list[dict], orders: list[dict]
) -> tuple[list[dict], list]:
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    eligible_indices = [
        index
        for index, account in enumerate(accounts)
        if account.get("DEL_FLG") != "Y"
        and account.get("ACCT_TYP") == "C"
    ]

    def compare_indices(left: int, right: int) -> int:
        result = _ascending_compare(
            accounts[left].get("ACCT_ID"),
            accounts[right].get("ACCT_ID"),
        )
        return result

    eligible_indices.sort(key=cmp_to_key(compare_indices))

    for account_index in eligible_indices:
        account = accounts[account_index]
        account_id = account.get("ACCT_ID")

        exposure = Decimal("0.00")
        for order in orders:
            if (
                order.get("DEL_FLG") != "Y"
                and order.get("ACCT_ID") == account_id
                and order.get("STAT_CD") == "I"
            ):
                exposure += _money(order.get("TOT_AMT"))

        limit = _money(account.get("CRED_LIMIT"))
        updated = new_accounts[account_index]
        held = account.get("CRED_HOLD") == "Y"

        if exposure > limit and not held:
            updated["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", account_id))
            held = True

        if exposure <= (limit * Decimal("8") / Decimal("10")) and held:
            updated["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", account_id))

    return new_accounts, audits
